var idx=lang==="en"?0:1;
function tr(s){
  if(lang==="pt"||typeof s!=="string") return s;
  var t=s.trim(); if(!t) return s;
  var out=t;
  if(DIC[t]) out=DIC[t][idx];
  else { for(var i=0;i<RULES.length;i++){ var re=new RegExp(RULES[i][0]); if(re.test(out)) out=out.replace(re,RULES[i][1+idx]); } }
  if(out===t) return s;
  var lead=s.match(/^\s*/)[0], trail=s.match(/\s*$/)[0];
  return lead+out+trail;
}
function walk(o){
  if(Array.isArray(o)) return o.map(walk);
  if(o&&typeof o==="object"){ for(var k in o){ if(Object.prototype.hasOwnProperty.call(o,k)) o[k]=walk(o[k]); } return o; }
  return typeof o==="string"?tr(o):o;
}
